    GPIOA->MODER |= (0x2U << GPIO_MODER_MODE6_Pos);          /* AF mode */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |= (0x2U << GPIO_AFRL_AFSEL6_Pos);         /* AF2 */
    GPIOA->OSPEEDR |= (0x2U << GPIO_OSPEEDR_OSPEED6_Pos);     /* High speed */

    /* =========================================================================
     * 3. TIM2 Configuration: 1 kHz, 50 % Duty Cycle PWM on PA0
     *    - TIMCLK = 170 MHz
     *    - Prescaler: 169 + 1 -> 1 MHz tick (1 µs)
     *    - Period: ARR = 999 + 1 -> 1000 µs = 1 ms (1 kHz)
     *    - Pulse: CCR1 = 500 (500 µs / 1000 µs = 50 %)
     * ========================================================================= */
    TIM2->PSC   = 169U;
    TIM2->ARR   = 999U;
    TIM2->CCR1  = 500U;

    TIM2->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM2->CCMR1 |= (0x6U << TIM_CCMR1_OC1M_Pos);             /* PWM mode 1 */
    TIM2->CCMR1 |= TIM_CCMR1_OC1PE;                          /* Preload CCR1 */

