    TIM2->EGR    = TIM_EGR_UG;                               /* Load registers */
    TIM2->CR1   |= TIM_CR1_CEN;                              /* Start TIM2 */

    /* =========================================================================
     * 4. TIM3 Configuration: 50 Hz Servo Signal on PA6
     *    - TIMCLK = 170 MHz
     *    - Prescaler: 169 + 1 -> 1 MHz tick (1 µs)
     *    - Period: ARR = 19999 + 1 -> 20,000 µs = 20 ms (50 Hz)
     *    - Pulse: CCR1 = 1500 (1.5 ms neutral position; 1000–2000 µs range)
     * ========================================================================= */
    TIM3->PSC   = 169U;
    TIM3->ARR   = 19999U;
    TIM3->CCR1  = 1500U;

    TIM3->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM3->CCMR1 |= (0x6U << TIM_CCMR1_OC1M_Pos);             /* PWM mode 1 */
    TIM3->CCMR1 |= TIM_CCMR1_OC1PE;                          /* Preload CCR1 */

    TIM3->CCER  &= ~TIM_CCER_CC1P;                           /* Active-high */
    TIM3->CCER  |= TIM_CCER_CC1E;                            /* Output enable */

    TIM3->CR1   |= TIM_CR1_ARPE;                             /* Preload ARR */
    TIM3->EGR    = TIM_EGR_UG;                               /* Load registers */
    TIM3->CR1   |= TIM_CR1_CEN;                              /* Start TIM3 */

