#include "stm32g4xx.h"

int main(void)
{
    /* ---------------- 1. CLOCK CONFIGURATION (170 MHz) ---------------- */
    // Enable Power Control clock and set voltage scaling to Range 1 Boost
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    PWR->CR1 &= ~PWR_CR1_VOS;
    PWR->CR1 |= (1U << PWR_CR1_VOS_Pos);      // Range 1
    PWR->CR5 &= ~PWR_CR5_R1MODE;              // Boost mode enabled (0 = boost)

    // Flash latency for 170 MHz requires 4 wait states (Vcore Range 1 Boost)
    FLASH->ACR &= ~FLASH_ACR_LATENCY;
    FLASH->ACR |= FLASH_ACR_LATENCY_4WS;

    // Enable HSI16 and wait for ready
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));

    // Configure PLL: HSI (16 MHz) / M(4) * N(85) / R(2) = 170 MHz
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI |
                   (3U << RCC_PLLCFGR_PLLM_Pos)   | // PLLM = 4 (bits 011)
                   (85U << RCC_PLLCFGR_PLLN_Pos)  | // PLLN = 85
                   (0U << RCC_PLLCFGR_PLLR_Pos)   | // PLLR = 2 (bits 00)
                   RCC_PLLCFGR_PLLREN;

    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    // Select PLL as SYSCLK
    RCC->CFGR &= ~RCC_CFGR_SW;
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    /* ---------------- 2. GPIO CLOCKS ENABLE ---------------- */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN | RCC_AHB2ENR_GPIOCEN;

    /* ---------------- 3. USART3 CONFIGURATION (PC10/PC11) --- */
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    // Set PC10 and PC11 to Alternate Function AF7 (USART3 TX/RX)
    GPIOC->MODER &= ~((3U << (10 * 2)) | (3U << (11 * 2)));
    GPIOC->MODER |=  ((2U << (10 * 2)) | (2U << (11 * 2)));
    GPIOC->AFR[1] |= (7U << ((10 - 8) * 4)) | (7U << ((11 - 8) * 4));

    // Baud rate = 170 MHz / 115200 = 1476
    USART3->BRR = 1476;
    USART3->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* ---------------- 4. HEATER PWM CONFIGURATION (PB10, TIM2_CH3) ---------------- */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM2EN;

    // Set PB10 to Alternate Function AF1 (TIM2_CH3)
    GPIOB->MODER &= ~(3U << (10 * 2));
    GPIOB->MODER |=  (2U << (10 * 2));
    GPIOB->AFR[1] |= (1U << ((10 - 8) * 4));

    // TIM2 Base: Prescaler = 0, Period = 33999 (5 kHz at 170 MHz)
    TIM2->PSC = 0;
    TIM2->ARR = 33999;

    // TIM2 CH3: PWM Mode 1 (OC3M = 0110), Preload Enable (OC3PE = 1)
    TIM2->CCMR2 |= (6U << TIM_CCMR2_OC3M_Pos) | TIM_CCMR2_OC3PE;

    // Duty Cycle = 80 % of 34000 = 27200
    TIM2->CCR3 = 27200;

    // Output Polarity Active High (CC3P = 0), Enable Output (CC3E = 1)
    TIM2->CCER &= ~TIM_CCER_CC3P;
    TIM2->CCER |= TIM_CCER_CC3E;

    // Enable Auto-reload preload and start timer
    TIM2->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    /* ---------------- 5. MAIN LOOP ---------------- */
    while (1)
