    GPIOB->MODER &= ~(3U << (10 * 2));
    GPIOB->MODER |=  (2U << (10 * 2));
    GPIOB->AFR[1] |= (1U << ((10 - 8) * 4));

    // TIM2 Base: Prescaler = 0, Period = 33999 (5 kHz at 170 MHz)
    TIM2->PSC = 0;
    TIM2->ARR = 33999;

