Here is the register-level initialization for USART1 on STM32G474:

```c
#include "stm32g4xx.h"

void USART1_Debug_Init(uint32_t f_ck)
{
    /* 1. Enable clocks for GPIOA and USART1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* 2. Configure PA9 (TX) and PA10 (RX) as Alternate Function (AF7) */
    // Alternate Function mode (0b10)
    GPIOA->MODER &= ~(GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk);
    GPIOA->MODER |=  (2U << GPIO_MODER_MODE9_Pos) | (2U << GPIO_MODER_MODE10_Pos);

    // Set AF7 (USART1) in AFRH for pins 9 and 10
    GPIOA->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL9_Pos) | (0xFU << GPIO_AFRH_AFSEL10_Pos));
    GPIOA->AFR[1] |=  (7U << GPIO_AFRH_AFSEL9_Pos)   | (7U << GPIO_AFRH_AFSEL10_Pos);

    // High speed on TX pin
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* 3. Configure USART1 */
    // Ensure USART is disabled before configuration
    USART1->CR1 = 0;

    // 1 stop bit (STOP[1:0] = 00)
    USART1->CR2 &= ~USART_CR2_STOP_Msk;

    // Oversampling by 16: OVER8 = 0
    USART1->CR1 &= ~USART_CR1_OVER8;

    // Set baud rate (BRR written before USART is enabled)
    // For OVER8 = 0, BRR = f_ck / baud_rate
    USART1->BRR = (f_ck + (115200U / 2U)) / 115200U;

    // 8 data bits (M[1:0] = 00), No parity (PCE = 0), Enable TX & RX
    USART1->CR1 |= (USART_CR1_TE | USART_CR1_RE);

    // 4. Enable USART
    USART1->CR1 |= USART_CR1_UE;
}
