### 1. Clock Configuration (SYSCLK = HCLK = PCLK1 = PCLK2 = 180 MHz)
Using 16 MHz HSI as PLL source ($f_{VCO} = \frac{16\text{ MHz}}{M=4} \times N=90 = 360\text{ MHz}$, $SYSCLK = \frac{360\text{ MHz}}{R=2} = 180\text{ MHz}$):

```c
#include "stm32g4xx.h"

void SystemClock_180MHz_Init(void)
{
    /* 1. Enable PWR clock and enable Range 1 Boost Mode */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    PWR->CR1 &= ~PWR_CR1_VOS_Msk;
    PWR->CR1 |= (1U << PWR_CR1_VOS_Pos);  // Range 1
    PWR->CR5 &= ~PWR_CR5_R1MODE;          // Clear R1MODE to enable Boost mode

    /* 2. Configure Flash Latency (5 WS for 180 MHz) and prefetch */
    FLASH->ACR &= ~FLASH_ACR_LATENCY_Msk;
    FLASH->ACR |= FLASH_ACR_LATENCY_5WS | FLASH_ACR_PRFTEN;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_5WS);

    /* 3. Ensure HSI is enabled and ready */
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));

    /* 4. Configure PLL: HSI (16 MHz) / 4 * 90 / 2 = 180 MHz */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI |
                   (3U << RCC_PLLCFGR_PLLM_Pos)  | // M = 4 (value = 3)
                   (90U << RCC_PLLCFGR_PLLN_Pos) | // N = 90
                   (0U << RCC_PLLCFGR_PLLR_Pos)  | // R = 2 (value = 0)
                   RCC_PLLCFGR_PLLREN;

    /* 5. Enable PLL */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* 6. Keep all prescalers at 1 (HPRE = 1, PPRE1 = 1, PPRE2 = 1) */
    RCC->CFGR &= ~(RCC_CFGR_HPRE_Msk | RCC_CFGR_PPRE1_Msk | RCC_CFGR_PPRE2_Msk);

    /* 7. Switch SYSCLK to PLL */
    RCC->CFGR &= ~RCC_CFGR_SW_Msk;
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL);
}
