### 2. Peripheral Adjustments for 180 MHz Bus Clock

```c
void Peripherals_Update_180MHz(void)
{
    /* --- USART1: 115200 baud at 180 MHz (OVER8 = 0) --- */
    // BRR = 180,000,000 / 115,200 = 1562.5 -> 1563 (0x61B)
    USART1->CR1 &= ~USART_CR1_UE;
    USART1->BRR = (180000000U + (115200U / 2U)) / 115200U;
    USART1->CR1 |= USART_CR1_UE;

    /* --- I2C2: 100 kHz Standard Mode at 180 MHz --- */
    // TIMINGR recalculation with PRESC = 15 (t_I2CCLK = 88.88 ns):
    // SCLL = 0x5C (93), SCLH = 0x57 (88), SDADEL = 0x2, SCLDEL = 0x4
    I2C2->CR1 &= ~I2C_CR1_PE;
    I2C2->TIMINGR = (15U << I2C_TIMINGR_PRESC_Pos) |
                    (4U  << I2C_TIMINGR_SCLDEL_Pos) |
                    (2U  << I2C_TIMINGR_SDADEL_Pos) |
                    (0x57U << I2C_TIMINGR_SCLH_Pos) |
                    (0x5CU << I2C_TIMINGR_SCLL_Pos);
    I2C2->CR1 |= I2C_CR1_PE;

    /* --- TIM3 (LED PWM): 1 kHz, 50% duty at 180 MHz --- */
    // Timer clock = PCLK1 = 180 MHz. PSC = 180 - 1 = 179 gives 1 MHz timer tick.
    TIM3->PSC = (180000000U / 1000000U) - 1U; // 179
    TIM3->EGR |= TIM_EGR_UG;                   // Load shadow register immediately
}
