    GPIOA->AFR[0] &= ~(GPIO_AFRL_AFSEL2_Msk | GPIO_AFRL_AFSEL3_Msk);
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL2_Pos) | (7U << GPIO_AFRL_AFSEL3_Pos);

    /* 3. Configure Baud Rate:
     * Clock source is PCLK1 = 16,000,000 Hz (default after reset).
     * Oversampling by 16 (OVER8 = 0):
     * BRR = 16,000,000 / 9600 = 1666.667 -> 1667 (0x0683).
     * Actual baud rate = 16,000,000 / 1667 ≈ 9598.08 baud (error ≈ -0.02%).
     * Written before enabling the USART [RM0440 p.1269].
     */
    USART2->BRR = 1667U;

    /* 4. Configure frame format and enable transmitter and receiver:
     * Reset defaults provide 8 data bits (M[1:0] = 00), 1 stop bit (STOP[1:0] = 00 in CR2),
     * parity disabled (PCE = 0), and oversampling by 16 (OVER8 = 0 in CR1).
     */
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE;

