### Complete Firmware Initialization Program

Here is the complete bare-metal initialization program covering the design requested across all messages:
1. **Clock tree**: 170 MHz SYSCLK/HCLK/PCLK1/PCLK2 generated via HSE (8 MHz) and PLL in Range 1 Boost mode with 4 Flash wait states.
2. **USART1**: Debug port at 115,200 baud on PA9 (TX) and PA10 (RX), 8 data bits, 1 stop bit, no parity, oversampling by 16.
3. **TIM3 CH1**: 1 kHz status LED PWM with 50% duty cycle on PB4 (AF2, edge-aligned mode 1).
4. **I2C2 Sensor Notes**: Hardware pin conflict analysis on PA9 and 1.8 V logic-level translation requirements are explained below.

---

```c
#include "stm32g4xx.h"

int main(void)
{
    /* =========================================================================
     * 1. CLOCK CONFIGURATION (170 MHz via HSE 8 MHz + PLL)
     * ========================================================================= */
    /* Enable Power Interface clock in APB1 to access PWR registers */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* Switch to Voltage Scaling Range 1 Boost mode (R1MODE = 0) */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Set Flash latency to 4 wait states for 170 MHz in Range 1 Boost mode */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;

    /* Enable HSE crystal oscillator and wait for it to stabilize */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Busy wait */
    }

    /* Configure PLL:
     *   Source = HSE (8 MHz)
     *   PLLM = 2  (/2 -> 4 MHz VCO input)
     *   PLLN = 85 (*85 -> 340 MHz VCO)
     *   PLLR = 2  (/2 -> 170 MHz PLLCLK)
     *   Enable PLL 'R' output (PLLREN)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (1U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Busy wait */
    }

    /* Intermediate step: divide HCLK by 2 before switching SYSCLK to PLL > 80 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;

    /* Select PLL as SYSCLK source */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;

    /* Wait until PLL is selected as system clock source */
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Busy wait */
    }

    /* Wait >= 1 us transition delay, then restore AHB prescaler to DIV1 (170 MHz) */
    for (volatile uint32_t i = 0; i < 50; i++) {
        __NOP();
    }
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;

    /* =========================================================================
     * 2. GPIO PORT CLOCK ENABLES
     * ========================================================================= */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN;

    /* =========================================================================
     * 3. USART1 CONFIGURATION (PA9 = TX, PA10 = RX @ 115200 baud)
     * ========================================================================= */
    /* Enable USART1 peripheral clock (APB2) */
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* Configure PA9 and PA10 in Alternate Function mode (MODER = 10b) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE9_Pos) | (2U << GPIO_MODER_MODE10_Pos);

    /* Map PA9 and PA10 to AF7 (USART1_TX / USART1_RX) in GPIOA_AFRH */
    GPIOA->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL9_Pos) | (0xFU << GPIO_AFRH_AFSEL10_Pos));
    GPIOA->AFR[1] |= (7U << GPIO_AFRH_AFSEL9_Pos) | (7U << GPIO_AFRH_AFSEL10_Pos);

    /* Reset USART1 control registers */
    USART1->CR1 = 0;
    USART1->CR2 = 0;
    USART1->CR3 = 0;

    /* Set Baud Rate register before enabling USART1:
     *   PCLK2 = 170 MHz, Baud = 115200, OVER8 = 0
     *   USARTDIV = 170,000,000 / 115,200 = 1475.694 -> BRR = 1476
     *   Actual baud = 115,176.15 baud (-0.021% error)
     */
    USART1->BRR = 1476;

    /* Enable Transmitter (TE), Receiver (RE), and USART peripheral (UE) */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* =========================================================================
     * 4. TIM3 PWM CONFIGURATION (PB4 = TIM3_CH1 @ 1 kHz, 50% Duty Cycle)
     * ========================================================================= */
    /* Enable TIM3 peripheral clock (APB1) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    /* Configure PB4 in Alternate Function mode (MODER4 = 10b) */
    GPIOB->MODER &= ~GPIO_MODER_MODE4_Msk;
    GPIOB->MODER |= (2U << GPIO_MODER_MODE4_Pos);

    /* Map PB4 to AF2 (TIM3_CH1) in GPIOB_AFRL */
    GPIOB->AFR[0] &= ~GPIO_AFRL_AFSEL4_Msk;
    GPIOB->AFR[0] |= (2U << GPIO_AFRL_AFSEL4_Pos);

    /* Configure timer timebase:
     *   TIMxCLK = 170 MHz (APB prescaler = 1)
     *   PSC = 3 -> timer clock = 170 MHz / 4 = 42.5 MHz
     *   ARR = 42499 -> period = 42500 counts (1000.0 Hz)
     *   CCR1 = 21250 -> 50.0% duty cycle
     */
    TIM3->PSC = 3;
    TIM3->ARR = 42499;
    TIM3->CCR1 = 21250;

    /* Configure Channel 1: PWM mode 1 (OC1M = 0110b), preload enable (OC1PE = 1) */
    TIM3->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Enable output on Channel 1 (CC1E = 1), active-high polarity (CC1P = 0) */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* Generate update event to transfer values to shadow registers */
    TIM3->EGR |= TIM_EGR_UG;

    /* Enable auto-reload preload (ARPE) and start counter (CEN) */
    TIM3->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    /* =========================================================================
     * Main Loop
     * ========================================================================= */
