    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* Temporarily divide HCLK by 2 before entering boost mode */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV2;

    /* Enable Range 1 Boost mode by clearing R1MODE in PWR_CR5 */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Set Flash latency: 4 WS (5 CPU cycles) required for 170 MHz in Range 1 Boost */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    /* Start HSE oscillator and wait for ready */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    /* Configure PLL: HSE (8 MHz) / PLLM(2) * PLLN(85) / PLLR(2) = 170 MHz */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (1U << RCC_PLLCFGR_PLLM_Pos) | /* PLLM = 2 (field value 1) */
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   (0U << RCC_PLLCFGR_PLLR_Pos) | /* PLLR = 2 (field value 0) */
                   RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* Switch system clock to PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    /* Restore AHB prescaler to 1; APB1 and APB2 prescalers remain 1 */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE) | RCC_CFGR_HPRE_DIV1;
    RCC->CFGR &= ~(RCC_CFGR_PPRE1 | RCC_CFGR_PPRE2);

    /* =========================================================================
     * 2. USART1 CONFIGURATION (115200 Baud on PA9 / PA10)
     * ========================================================================= */
    /* Enable GPIOA and USART1 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* PA9 (TX) and PA10 (RX): Alternate Function mode */
    GPIOA->MODER = (GPIOA->MODER & ~(GPIO_MODER_MODE9_Msk | GPIO_MODER_MODE10_Msk))
                 | (2U << GPIO_MODER_MODE9_Pos)
                 | (2U << GPIO_MODER_MODE10_Pos);

    /* Route PA9 and PA10 to AF7 (USART1) */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(GPIO_AFRH_AFSEL9_Msk | GPIO_AFRH_AFSEL10_Msk))
                  | (7U << GPIO_AFRH_AFSEL9_Pos)
                  | (7U << GPIO_AFRH_AFSEL10_Pos);

    /* Ensure USART1 is disabled before programming (UE = 0) */
    USART1->CR1 = 0;
    USART1->CR2 = 0;
    USART1->CR3 = 0;

    /* Program baud rate register before enabling:
     * Clock = PCLK2 = 170 MHz, OVER8 = 0
     * BRR = 170000000 / 115200 = 1475.694 -> 1476 (0x5C4, -0.02% error)
     */
    USART1->BRR = 1476U;

    /* Enable transmitter (TE) and receiver (RE), then enable USART1 (UE) */
    USART1->CR1 |= (USART_CR1_TE | USART_CR1_RE);
    USART1->CR1 |= USART_CR1_UE;

    /* =========================================================================
     * 3. TIM3 PWM CONFIGURATION (1 kHz, 50% duty on PB4)
     * ========================================================================= */
    /* Enable GPIOB and TIM3 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    /* Configure PB4 as Alternate Function mode */
    GPIOB->MODER = (GPIOB->MODER & ~GPIO_MODER_MODE4_Msk) | (2U << GPIO_MODER_MODE4_Pos);

    /* Route PB4 to AF2 (TIM3_CH1) */
    GPIOB->AFR[0] = (GPIOB->AFR[0] & ~GPIO_AFRL_AFSEL4_Msk) | (2U << GPIO_AFRL_AFSEL4_Pos);

    /* Time base: 170 MHz / ((3 + 1) * (42499 + 1)) = 1000 Hz */
    TIM3->PSC = 3U;
    TIM3->ARR = 42499U;
    TIM3->CCR1 = 21250U; /* 50% duty cycle (21250 / 42500) */

    /* Output compare: PWM Mode 1, preload enabled */
    TIM3->CCMR1 = (TIM3->CCMR1 & ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk))
                | TIM_CCMR1_OC1PE
                | (6U << TIM_CCMR1_OC1M_Pos);

    /* Active-high polarity, enable channel 1 output */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* Enable auto-reload preload and start timer */
    TIM3->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    /* =========================================================================
     * 4. I2C2 CONFIGURATION (100 kHz Standard Mode, PC4 SCL, PA8 SDA)
     * ========================================================================= */
    /* Enable GPIOC and I2C2 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C2EN;

    /* Ensure HSI16 is enabled and select HSI16 (16 MHz) as I2C2 kernel clock */
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));
    RCC->CCIPR = (RCC->CCIPR & ~RCC_CCIPR_I2C2SEL_Msk) | (2U << RCC_CCIPR_I2C2SEL_Pos);

    /* Configure PC4 (SCL): AF4, Open-Drain, Pull-up, High Speed */
    GPIOC->MODER = (GPIOC->MODER & ~GPIO_MODER_MODE4_Msk) | (2U << GPIO_MODER_MODE4_Pos);
    GPIOC->OTYPER |= GPIO_OTYPER_OT4;
    GPIOC->PUPDR = (GPIOC->PUPDR & ~GPIO_PUPDR_PUPD4_Msk) | (1U << GPIO_PUPDR_PUPD4_Pos);
    GPIOC->OSPEEDR = (GPIOC->OSPEEDR & ~GPIO_OSPEEDR_OSPEED4_Msk) | (3U << GPIO_OSPEEDR_OSPEED4_Pos);
    GPIOC->AFR[0] = (GPIOC->AFR[0] & ~GPIO_AFRL_AFSEL4_Msk) | (4U << GPIO_AFRL_AFSEL4_Pos);

    /* Configure PA8 (SDA): AF4, Open-Drain, Pull-up, High Speed */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk) | (2U << GPIO_MODER_MODE8_Pos);
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;
    GPIOA->PUPDR = (GPIOA->PUPDR & ~GPIO_PUPDR_PUPD8_Msk) | (1U << GPIO_PUPDR_PUPD8_Pos);
    GPIOA->OSPEEDR = (GPIOA->OSPEEDR & ~GPIO_OSPEEDR_OSPEED8_Msk) | (3U << GPIO_OSPEEDR_OSPEED8_Pos);
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~GPIO_AFRH_AFSEL8_Msk) | (4U << GPIO_AFRH_AFSEL8_Pos);

    /* Disable I2C2 before programming TIMINGR (PE = 0) */
    I2C2->CR1 &= ~I2C_CR1_PE;

    /* Program TIMINGR for 100 kHz standard mode with 16 MHz kernel clock:
     * PRESC = 3 (0x3), SCLDEL = 4 (0x4), SDADEL = 2 (0x2), SCLH = 15 (0x0F), SCLL = 19 (0x13)
     */
    I2C2->TIMINGR = 0x30420F13U;

    /* Enable I2C2 peripheral (PE = 1) */
    I2C2->CR1 |= I2C_CR1_PE;

    /* Loop forever */
    while (1)
    {
    }
}
