#include "stm32g4xx.h"

void init_system(void) {
    /* ---------------------------------------------------------
     * 1. Clock Setup (from Message 1): 170 MHz PLL from 8 MHz HSE
     * --------------------------------------------------------- */
    /* Enable power interface clock and enter Range 1 boost mode */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Configure Flash latency: 4 wait states for 170 MHz in Range 1 boost */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    /* Enable HSE and wait until ready */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    /* Configure PLL: HSE = 8 MHz, PLLM = 2 (/2 -> 4 MHz), PLLN = 85 (*85 -> 340 MHz VCO),
     * PLLR = 2 (/2 -> 170 MHz PLLCLK), enable PLL "R" output */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (1U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait until locked */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* Switch SYSCLK to PLL and wait until switched */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    /* ---------------------------------------------------------
     * 2. Peripheral Clocks
     * --------------------------------------------------------- */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* ---------------------------------------------------------
     * 3. GPIO Configuration: PA9 (TX) and PA10 (RX) to AF7
     * --------------------------------------------------------- */
    /* Set PA9 and PA10 to Alternate Function mode (0b10) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE9 | GPIO_MODER_MODE10);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE9_Pos) | (2U << GPIO_MODER_MODE10_Pos);

    /* Set AF7 (0b0111) for PA9 and PA10 in AFRH (AFR[1]) */
    GPIOA->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL9_Pos) | (0xFU << GPIO_AFRH_AFSEL10_Pos));
    GPIOA->AFR[1] |= (7U << GPIO_AFRH_AFSEL9_Pos) | (7U << GPIO_AFRH_AFSEL10_Pos);

    /* ---------------------------------------------------------
     * 4. USART1 Configuration: 115200 baud, 8N1, OVER16
     * --------------------------------------------------------- */
    /* Disable USART1 before writing configuration and BRR */
    USART1->CR1 = 0;
    USART1->CR2 = 0; /* 1 stop bit (STOP[1:0] = 00) */
    USART1->CR3 = 0;

    /* Program Baud Rate: 170 MHz / 115200 = 1475.69 -> 1476 */
    USART1->BRR = 1476U;

    /* Enable Transmitter (TE), Receiver (RE), and USART (UE) */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;
}
