    RCC->AHB2ENR   |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1  |= RCC_APB1ENR1_I2C2EN;

    /* ---------------------------------------------------------
     * 2. GPIO Configuration: PA8 (SDA) and PA9 (SCL) on AF4
     * --------------------------------------------------------- */
    /* Configure PA8 and PA9 as Alternate Function mode (0b10) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE8 | GPIO_MODER_MODE9);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos);

    /* Configure PA8 and PA9 as Open-Drain (OT = 1) */
    GPIOA->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* Configure Pull-up resistors (PUPDR = 0b01) */
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9);
    GPIOA->PUPDR |= (1U << GPIO_PUPDR_PUPD8_Pos) | (1U << GPIO_PUPDR_PUPD9_Pos);

    /* Set AF4 (0b0100) for PA8 and PA9 in AFRH (AFR[1]) */
    GPIOA->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL8_Pos) | (0xFU << GPIO_AFRH_AFSEL9_Pos));
    GPIOA->AFR[1] |= (4U << GPIO_AFRH_AFSEL8_Pos) | (4U << GPIO_AFRH_AFSEL9_Pos);

    /* ---------------------------------------------------------
     * 3. I2C2 Configuration: Controller mode, 100 kHz Standard Mode
     * --------------------------------------------------------- */
    /* Ensure I2C2 is disabled before programming TIMINGR (PE = 0) */
    I2C2->CR1 &= ~I2C_CR1_PE;

    /* Configure timing register for standard mode 100 kHz with 16 MHz kernel clock:
     * PRESC  = 3    (Prescaler = 4 -> 250 ns clock period)
     * SCLDEL = 4    (Data setup time = 5 * 250 ns = 1250 ns)
     * SDADEL = 2    (Data hold time = 2 * 250 ns = 500 ns)
     * SCLH   = 0x0F (SCL high period = 16 * 250 ns = 4.0 us)
     * SCLL   = 0x13 (SCL low period = 20 * 250 ns = 5.0 us)
     * Value: 0x30420F13
     */
    I2C2->TIMINGR = (3U << I2C_TIMINGR_PRESC_Pos)   |
                    (4U << I2C_TIMINGR_SCLDEL_Pos)  |
                    (2U << I2C_TIMINGR_SDADEL_Pos)  |
                    (0x0FU << I2C_TIMINGR_SCLH_Pos) |
                    (0x13U << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C2 peripheral (PE = 1) */
    I2C2->CR1 |= I2C_CR1_PE;
